const $=s=>document.querySelector(s), money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100), label=s=>String(s).replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase());
const state={me:null,people:[],units:[],locations:[],filter:'All'};const MAYA='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa';
function user(){return localStorage.getItem('gearvault-demo-user')||MAYA}function ticket(){return crypto.randomUUID()}
async function api(url,options={}){const headers={'X-Demo-User':user(),...(options.body?{'Content-Type':'application/json','Idempotency-Key':options.ticket||ticket()}:{})};const r=await fetch(url,{...options,headers:{...headers,...options.headers}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request could not be completed.');return d}
function flash(msg,error=false){$('#notice').innerHTML=`<div class="${error?'error':''}">${msg}</div>`;setTimeout(()=>$('#notice').innerHTML='',5000)}
function status(s){return `<span class="status ${s==='AVAILABLE'||['PAID','COMPLETED'].includes(s)?'':'bad'}">${label(s)}</span>`}function fmtDate(d){return String(d).slice(0,10)}
async function boot(){try{const p=await api('/api/people');state.people=p.people;const chosen=state.people.find(x=>x.id===user())||state.people.find(x=>x.id===MAYA);localStorage.setItem('gearvault-demo-user',chosen.id);$('#person').innerHTML=state.people.map(x=>`<option value="${x.id}" ${x.id===chosen.id?'selected':''}>${x.full_name} · ${label(x.role)}</option>`).join('');await load();const q=new URLSearchParams(location.search);if(q.get('checkout')==='success'&&q.get('session_id')){await api('/api/payments/confirm',{method:'POST',body:JSON.stringify({session_id:q.get('session_id')})});history.replaceState({},'',location.pathname);flash('Payment confirmed — your dates are now held.');await load();showRecords()}else if(q.get('checkout')==='cancelled'){history.replaceState({},'',location.pathname);flash('Checkout was cancelled. No dates were held.',true)}}catch(e){flash(e.message,true)}}
async function load(){const d=await api('/api/overview');Object.assign(state,d);renderNav();renderHome()}
function renderNav(){const customer=state.me.role==='customer';$('#nav').innerHTML=customer?'<a href="#catalog">Catalog</a><a href="#records" data-view="records">My rentals</a><a href="#records" data-view="records">My records</a>':'<a href="#workspace">Workspace</a><a href="#catalog">Fleet</a>';$('#heroActions').innerHTML=`<a class="btn" href="#${customer?'catalog':'workspace'}">${customer?'Browse equipment':'Open my workspace'}</a>`;document.querySelectorAll('[data-view=records]').forEach(a=>a.onclick=e=>{e.preventDefault();showRecords()})}
function actionButton(r,role){if(role==='bay_technician'&&r.status==='PAID')return `<button class="btn" data-action="scan" data-id="${r.id}">Confirm bay & issue scan</button>`;if(role==='rental_associate'&&r.status==='PAID')return `<button class="btn dark" data-action="checkout" data-id="${r.id}">Check kit out</button>`;if(role==='rental_associate'&&r.status==='CHECKED_OUT')return `<button class="btn" data-action="return" data-id="${r.id}">Take return</button>`;if(role==='damage_assessor'&&r.status==='AWAITING_INSPECTION')return `<button class="btn dark" data-action="inspect" data-id="${r.id}">Inspect return</button>`;return ''}
async function renderWorkspace(){try{const d=await api('/api/operations');const role=state.me.role;let title={rental_associate:'Counter handover & returns',bay_technician:'Serial bay',damage_assessor:'Inspection corner',shop_manager:'Manager decisions & repair bay',transfer_clerk:'Shop transfers',night_auditor:'Night books',insurance_liaison:'Hull binds',lot_runner:'Lot overview'}[role]||'Workspace';let body='';if(['rental_associate','bay_technician','damage_assessor'].includes(role)){const wanted=role==='damage_assessor'?d.reservations.filter(r=>r.status==='AWAITING_INSPECTION'):d.reservations.filter(r=>['PAID','CHECKED_OUT'].includes(r.status));body=`<div class="panel"><h3>Active papers</h3>${wanted.length?wanted.map(r=>`<div class="record"><div><h4>${r.asset_tag} · ${r.model}</h4><div class="muted">${r.customer_name} · ${r.location_name} · ${fmtDate(r.start_date)} — ${fmtDate(r.end_date)}</div>${status(r.status)}</div><div>${actionButton(r,role)}</div></div>`).join(''):'<div class="empty">Nothing is waiting in this queue.</div>'}</div>`}else if(role==='shop_manager'){body=`<div class="two-col"><div><div class="panel"><h3>Damage decisions</h3>${d.inspections.filter(i=>i.status==='PENDING').map(i=>`<div class="record"><div><h4>${i.asset_tag} · ${i.customer_name}</h4><div class="muted">${label(i.severity)} · ${i.notes||'No note'} · proposed ${money(i.proposed_cents)}</div></div><button class="btn" data-approve="${i.id}" data-proposed="${i.proposed_cents}">Decide deposit</button></div>`).join('')||'<div class="empty">No write-ups await a decision.</div>'}</div><div class="panel"><h3>Fleet wall cards & repair bay</h3>${d.units.map(u=>`<div class="record"><div><b>${u.asset_tag} · ${u.model}</b><div class="muted">${money(u.daily_rate_cents)}/day · ${status(u.status)}</div></div><button class="btn ghost" data-manage="${u.id}">Manage</button></div>`).join('')}</div></div><div class="panel"><h3>Customer standing</h3>${d.customers.map(c=>`<div class="record"><div><b>${c.full_name}</b><div class="muted">${label(c.account_status)} · Balance ${money(c.outstanding_balance_cents)}</div></div><button class="btn ghost" data-standing="${c.id}" data-current="${c.account_status}">${c.account_status==='ACTIVE'?'Place on hold':'Clear hold'}</button></div>`).join('')}</div><div class="panel"><h3>Audit log</h3>${auditTable(d.audit)}</div></div>`}else if(role==='transfer_clerk'){body=`<div class="panel"><h3>Idle floor stock</h3>${d.units.filter(u=>u.status==='AVAILABLE').map(u=>`<div class="record"><div><h4>${u.asset_tag} · ${u.model}</h4><span class="muted">Currently ${u.location_name}</span></div><div class="row"><select data-dest="${u.id}">${d.locations.filter(l=>l.id!==u.location_id).map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select><button class="btn" data-transfer="${u.id}">Request stamped move</button></div></div>`).join('')}</div>`}else if(role==='night_auditor'){body=`<div class="panel"><h3>Immutable activity book</h3>${auditTable(d.audit)}</div>`}else if(role==='insurance_liaison'){body=`<div class="panel"><h3>Signed hull binds</h3>${d.binds?.length?`<pre>${JSON.stringify(d.binds,null,2)}</pre>`:'<div class="empty">No hull binds have been recorded.</div>'}</div>`}else{body=`<div class="panel"><h3>Fleet overview</h3><p class="muted">Lot runners can see where gear rests, but cannot drive transfers or work the counter.</p><div class="grid">${d.units.map(card).join('')}</div></div>`}$('#content').innerHTML=`<div class="section" id="workspace"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">${label(role)}</p><h2>${title}</h2></div></div><div class="role-banner">Signed in as <b>${state.me.full_name}</b>. This workspace only offers work assigned to your role.</div>${body}</div>`;bindOps(d)}catch(e){flash(e.message,true)}}
function auditTable(log=[]){return `<table class="table"><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Record</th></tr></thead><tbody>${log.map(a=>`<tr><td>${new Date(a.created_at).toLocaleString()}</td><td>${a.actor_name}</td><td>${label(a.action)}</td><td>${a.entity_type} · ${a.entity_id.slice(0,8)}</td></tr>`).join('')}</tbody></table>`}
function bindOps(d){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.dataset.action==='inspect')return inspectDialog(b.dataset.id);try{const x=await api(`/api/reservations/${b.dataset.id}/${b.dataset.action}`,{method:'POST',body:'{}'});flash(x.message);await load()}catch(e){flash(e.message,true)}});document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveDialog(b.dataset.approve,b.dataset.proposed));document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>manageDialog(d.units.find(u=>u.id===b.dataset.manage)));document.querySelectorAll('[data-transfer]').forEach(b=>b.onclick=async()=>{try{const to=document.querySelector(`[data-dest="${b.dataset.transfer}"]`).value,x=await api(`/api/units/${b.dataset.transfer}/transfer`,{method:'POST',body:JSON.stringify({to_location_id:to})});flash(x.message);await load()}catch(e){flash(e.message,true)}});document.querySelectorAll('[data-standing]').forEach(b=>b.onclick=async()=>{try{const next=b.dataset.current==='ACTIVE'?'ON_HOLD':'ACTIVE',x=await api(`/api/customers/${b.dataset.standing}/standing`,{method:'POST',body:JSON.stringify({account_status:next})});flash(x.message);await load()}catch(e){flash(e.message,true)}})}
function inspectDialog(id){$('#dialogBody').innerHTML=`<h2>Inspect returned kit</h2><form id="inspectForm" class="stack"><div class="field"><label>Finding</label><select name="outcome"><option value="CLEAR">Clear — no damage</option><option value="DAMAGE">Damage found</option></select></div><div class="field"><label>Severity</label><select name="severity"><option>MINOR</option><option>MAJOR</option></select></div><div class="field"><label>Proposed deposit deduction (USD)</label><input name="proposed" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Inspection notes</label><textarea name="notes" required></textarea></div><button class="btn dark">File inspection</button></form>`;$('#dialog').showModal();$('#inspectForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.proposed_cents=Math.round(Number(f.proposed)*100);delete f.proposed;try{const x=await api(`/api/reservations/${id}/inspect`,{method:'POST',body:JSON.stringify(f)});$('#dialog').close();flash(x.message);await load()}catch(err){flash(err.message,true)}}}
function approveDialog(id,proposed){$('#dialogBody').innerHTML=`<h2>Decide deposit deduction</h2><form id="approveForm" class="stack"><div class="field"><label>Approved deduction (USD)</label><input name="approved" type="number" min="0" step="0.01" value="${proposed/100}"></div><div class="field"><label>Decision note</label><textarea name="notes"></textarea></div><button class="btn dark">Approve decision</button></form>`;$('#dialog').showModal();$('#approveForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.approved_cents=Math.round(Number(f.approved)*100);delete f.approved;try{const x=await api(`/api/inspections/${id}/approve`,{method:'POST',body:JSON.stringify(f)});$('#dialog').close();flash(x.message);await load()}catch(err){flash(err.message,true)}}}
function manageDialog(u){$('#dialogBody').innerHTML=`<p class="tag">${u.asset_tag}</p><h2>Manage ${u.model}</h2><form id="manageForm" class="stack"><div class="field"><label>Floor status</label><select name="status">${['AVAILABLE','IN_REPAIR','RETIRED'].map(s=>`<option ${s===u.status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Daily rate (USD)</label><input name="rate" type="number" min="0" step="0.01" value="${u.daily_rate_cents/100}"></div><div class="field"><label>Deposit (USD)</label><input name="deposit" type="number" min="0" step="0.01" value="${u.deposit_cents/100}"></div><button class="btn dark">Update wall card</button></form>`;$('#dialog').showModal();$('#manageForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),body={status:f.status,daily_rate_cents:Math.round(Number(f.rate)*100),deposit_cents:Math.round(Number(f.deposit)*100)};try{const x=await api(`/api/units/${u.id}/manage`,{method:'POST',body:JSON.stringify(body)});$('#dialog').close();flash(x.message);await load()}catch(err){flash(err.message,true)}}}
$('#person').onchange=async e=>{localStorage.setItem('gearvault-demo-user',e.target.value);await load();window.scrollTo({top:0,behavior:'smooth'})};$('#dialog .close').onclick=()=>$('#dialog').close();boot();
function renderHome(){if(state.me.role==='customer')renderCatalog();else renderWorkspace()}
function card(u){const available=u.status==='AVAILABLE';return `<article class="card" data-category="${u.category}"><div class="row between"><span class="tag">${u.asset_tag}</span>${status(u.status)}</div><h3>${u.model}</h3><div class="muted">${u.category} · ${u.location_name}</div><div class="meta"><div><div class="price">${money(u.daily_rate_cents)} <small>/ day</small></div></div><div>Deposit<br><b>${money(u.deposit_cents)}</b></div></div><div class="muted">Replacement ${money(u.replacement_value_cents)}${u.required_certification?` · Requires ${u.required_certification}`:''}</div>${available?`<button class="btn dark" data-book="${u.id}">View dates & book</button>`:'<button class="btn ghost" disabled>Not available for walk-up</button>'}</article>`}
function renderCatalog(){const cats=['All',...new Set(state.units.map(u=>u.category))];const list=state.filter==='All'?state.units:state.units.filter(u=>u.category===state.filter);$('#content').innerHTML=`<div class="section" id="catalog"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">THE EQUIPMENT WALL</p><h2>Choose your kit</h2><p>Every card is one physical, serialized unit.</p></div><div class="filters">${cats.map(c=>`<button class="${c===state.filter?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div></div><div class="grid">${list.map(card).join('')}</div></div>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderCatalog()});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>book(state.units.find(u=>u.id===b.dataset.book)))}
function book(u){const today=new Date();today.setDate(today.getDate()+1);const start=today.toISOString().slice(0,10);today.setDate(today.getDate()+2);const end=today.toISOString().slice(0,10);$('#dialogBody').innerHTML=`<p class="tag">${u.asset_tag} · ${u.location_name}</p><h2>${u.model}</h2><p class="muted">${money(u.daily_rate_cents)} per day · ${money(u.deposit_cents)} refundable deposit</p><form id="bookForm" class="stack"><div class="row"><div class="field"><label>Start day</label><input name="start_date" type="date" value="${start}" required></div><div class="field"><label>Return day</label><input name="end_date" type="date" value="${end}" required></div></div><button class="btn dark" type="submit">Get live price</button></form><div id="quote"></div>`;$('#dialog').showModal();$('#bookForm').onsubmit=async e=>{e.preventDefault();const body={unit_id:u.id,...Object.fromEntries(new FormData(e.target))};try{const d=await api('/api/quotes',{method:'POST',body:JSON.stringify(body)});const q=d.quote;$('#quote').innerHTML=`<div class="panel"><div class="row between"><b>${q.day_count} calendar day${q.day_count>1?'s':''}</b><span class="total">${money(q.total_cents)}</span></div><div class="breakdown"><div><span>Kit hire</span><b>${money(q.rental_cents)}</b></div>${q.discount_cents?`<div><span>7+ day saving</span><b>−${money(q.discount_cents)}</b></div>`:''}<div><span>Weekend line</span><b>${money(q.weekend_cents)}</b></div><div><span>County tax</span><b>${money(q.tax_cents)}</b></div><div><span>Hull insurance</span><b>${money(q.hull_cents)}</b></div><div><span>Refundable deposit</span><b>${money(q.deposit_cents)}</b></div></div><button class="btn" id="pay">Continue to secure Stripe Checkout</button><p class="muted">Dates are held only after Stripe confirms payment.</p></div>`;$('#pay').onclick=async()=>{try{const x=await api('/api/checkout',{method:'POST',body:JSON.stringify(body)});location.href=x.checkout_url}catch(err){flash(err.message,true)}}}catch(err){$('#quote').innerHTML=`<div class="role-banner">${err.message}</div>`}}}
async function showRecords(){try{const d=await api('/api/me/records');$('#content').innerHTML=`<div class="section" id="records"><div class="section-head"><div><p class="eyebrow" style="color:var(--rust)">YOUR GEARVAULT FILE</p><h2>Rentals & records</h2><p>Only records belonging to ${state.me.full_name} are shown.</p></div><button class="btn ghost" id="back">Back to catalog</button></div><div class="two-col"><div class="panel"><h3>Reservations</h3>${d.reservations.length?d.reservations.map(r=>`<div class="record"><div><h4>${r.asset_tag} · ${r.model}</h4><div class="muted">${fmtDate(r.start_date)} — ${fmtDate(r.end_date)} · ${r.location_name}</div><div>${status(r.status)} · Total ${money(r.total_cents)} · Deposit ${money(r.deposit_cents)}</div></div><div class="stack"><a class="btn ghost" href="/downloads/hire-waiver.pdf">Hire waiver PDF</a><button class="btn ghost" data-cal="${r.id}">Add to calendar</button>${r.status==='PAID'?`<button class="btn danger" data-cancel="${r.id}">Cancel rental</button>`:''}</div></div>`).join(''):'<div class="empty">No paid rentals yet. Unpaid checkouts never appear here.</div>'}</div><div><div class="panel"><h3>Operator cards</h3>${d.certifications.length?d.certifications.map(c=>`<p><b>${c.certification_type}</b><br><span class="muted">Valid through ${fmtDate(c.expires_on)}</span></p>`).join(''):'<p class="muted">No certifications on file.</p>'}</div><div class="panel"><h3>Delivery trail</h3><p><b>${(d.notices||[]).length}</b> paper copies</p><p><b>${(d.texts||[]).length}</b> texts · <b>${(d.emails||[]).length}</b> emails</p><p><b>${(d.holds||[]).length}</b> diary holds · <b>${(d.punches||[]).length}</b> loyalty punches</p></div></div></div></div>`;$('#back').onclick=renderCatalog;document.querySelectorAll('[data-cal]').forEach(b=>b.onclick=async()=>{const r=await fetch(`/api/reservations/${b.dataset.cal}/calendar.ics`,{headers:{'X-Demo-User':user()}});if(!r.ok)return flash((await r.json()).error,true);const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GearVault-hire.ics';a.click()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(confirm('Cancel this paid rental before pickup?'))try{const x=await api(`/api/reservations/${b.dataset.cancel}/cancel`,{method:'POST',body:'{}'});flash(x.message);showRecords();await load()}catch(e){flash(e.message,true)}})}catch(e){flash(e.message,true)}}
